def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split pre-release (everything after '-')
        if '-' in v_no_build:
            parts = v_no_build.split('-', 1)
            core = parts[0]
            prerelease = parts[1]
        else:
            core = v_no_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        version_parts = core.split('.')
        major = int(version_parts[0])
        minor = int(version_parts[1])
        patch = int(version_parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert to tuples for comparison
            parsed_identifiers = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_identifiers.append((0, int(identifier)))
                else:
                    parsed_identifiers.append((1, identifier))
            prerelease_tuple = tuple(parsed_identifiers)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(v):
        major, minor, patch, prerelease_tuple = parse_version(v)

        # If no pre-release, it sorts after the same version with pre-release
        # So we use a tuple: (major, minor, patch, has_prerelease, prerelease)
        # has_prerelease = (True, ...) if has pre-release, (False, ...) if no pre-release
        # But we want "no pre-release" to sort AFTER "with pre-release"
        # So we use: (major, minor, patch, prerelease is None, prerelease_tuple or ())

        if prerelease_tuple is None:
            return (major, minor, patch, (1,))  # 1 to sort after pre-release versions
        else:
            return (major, minor, patch, (0, prerelease_tuple))  # 0 to sort before non-pre-release

    # Sort with stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

